def main():
    import json
    import urllib.request
    from copy import deepcopy
    from pathlib import Path
    from project.llm.services.scenario import validate
    base='http://127.0.0.1:18765'
    with urllib.request.urlopen(base+'/api/state',timeout=10) as response:before=json.load(response)
    config=deepcopy(before['config'])
    for key,text in UI_TEXT.items():config['ui'][key]['text']=text
    for node in config['nodes']:
        if node['id'] in NODE_TEXT:node['text'],node['adult_text']=NODE_TEXT[node['id']]
    validate(config)
    request=urllib.request.Request(base+'/api/draft',method='PUT',
        data=json.dumps({'config':config,'revision':before['revision']},ensure_ascii=False).encode(),
        headers={'Content-Type':'application/json','X-Editor-Request':'local'})
    with urllib.request.urlopen(request,timeout=10) as response:saved=json.load(response)
    with urllib.request.urlopen(base+'/api/state',timeout=10) as response:after=json.load(response)
    assert after['revision']==saved['revision'] and after['published_id']==before['published_id']
    assert after['config']==config
    result={'revision_before':before['revision'],'revision':after['revision'],'published_id':after['published_id'],
            'ui_keys':list(UI_TEXT),'nodes':list(NODE_TEXT),'saved_texts_match':True}
    Path('docs/test-results/work-copy-update.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf8')
    print(json.dumps(result,ensure_ascii=False))


if __name__=='__main__':main()
